# Embed the eighteen registered response poses; idle images have a separate bank.
# Usage: ruby scripts/embed_robot_home_action_art.rb ASSET_DIRECTORY OUTPUT.h
abort 'expected ASSET_DIRECTORY OUTPUT.h' unless ARGV.size == 2
directory, output = ARGV
poses = [['BumblebeeFullbody', 1], ['BumblebeeFullbody', 2], ['Optimus', 1], ['Optimus', 2]] +
        %w[Jazz Hotrod Wheeljack Hound Ironhide Ratchet Megatron Starscream Soundwave Shockwave Thundercracker Skywarp Blitzwing Astrotrain].map { |hero| [hero, 1] }
text = <<~HEADER
  // SPDX-License-Identifier: MIT
  // Generated by scripts/embed_robot_home_action_art.rb. Do not edit by hand.
  #pragma once
  #include <cstddef>
  #include <cstdint>
  #if defined(ARDUINO)
  #include <pgmspace.h>
  #define ROBOT_HOME_ACTION_PROGMEM PROGMEM
  #else
  #define ROBOT_HOME_ACTION_PROGMEM
  #endif
  namespace robot_home::art_data {
HEADER
poses.each do |hero, pose|
  filename = "#{hero.downcase}-#{pose}.jpg"
  bytes = File.binread(File.join(directory, filename)).bytes
  abort "#{filename}: invalid JPEG" unless bytes.first(2) == [0xff, 0xd8] && bytes.last(2) == [0xff, 0xd9]
  abort "#{filename}: exceeds 50 KiB" unless bytes.size < 50 * 1024
  name = "#{hero}Pose#{pose}"
  text += "inline const std::uint8_t k#{name}Jpg[] ROBOT_HOME_ACTION_PROGMEM = {\n"
  bytes.each_slice(16) { |row| text += '  ' + row.map { |byte| format('0x%02x', byte) }.join(', ') + ",\n" }
  text += "};\ninline constexpr std::size_t k#{name}JpgSize = sizeof(k#{name}Jpg);\n"
end
text += "}  // namespace robot_home::art_data\n#undef ROBOT_HOME_ACTION_PROGMEM\n"
File.write(output, text)
